// fughetta-serena — фуга и канон in C минор, 66 BPM. Generated by MathMusic (style fugue, seed 1):
// canon → exposition → episode → middle entry → episode II → middle entry II → episode III → stretto → coda. Флейта, гобой, фагот → скрипка, альт, виолончель; клавесин-континуо; виолоне и орган в tutti.
// Composed by the rules of counterpoint (src/counterpoint.js, src/fugue.js) — consonance wherever a note begins on a beat,
// dissonance only as a passing or neighbour note, the fourth dissonant over the lowest voice, no parallel fifths or
// octaves, no crossing, leaps answered by steps, the raised 6th and 7th of minor going up; check() finds 0 faults.
// The canon: the soprano is followed by the alto a bar later and an octave lower, chosen note by note against that echo;
// the bass is free; at the end the follower leaves the canon for the cadence.
// The subject (8 beats): G4 A♭4 F4 E♭4 C4 B3 C4 E♭4 F4 G4 B4 C5 D5 C5; the answer is tonal (its head answers 5̂ by 1̂); the countersubject
// was written against the answer below it and the subject above it at once — invertible at the octave.
// Episodes: sequences down the circle of fifths, the soprano's motif (from the subject or the countersubject) a step lower
// each bar, the bass on the roots. Stretto: the subject against itself 4 beats later. Coda: iv – V – I with a Picardy third.
// Entries:
//   40: альт — subject (Cm)
//   48: сопрано — tonal answer (Gm)
//   60: бас — subject (Cm)
//   76: сопрано — subject (E♭)
//   92: альт — subject (Fm)
//   112: бас — subject (stretto) (Cm)
//   116: альт — subject in stretto, 4 beats later (Cm)
// x is time in beats; n counts semitones from C4 (MIDI 60). Draw the voices in the piano roll (P).
import { filter, floor, hz, mod, reverb, smooth } from '../src/engine.js'
import {
  bowed, flute, hash, notesAt, organ, pan, plucker, reed, trigger,
} from '../src/instruments.js'

const SECTIONS = [[0,"canon"],[40,"exposition"],[68,"episode"],[76,"middle entry"],[84,"episode II"],[92,"middle entry II"],[100,"episode III"],[112,"stretto"],[124,"coda"]]
const END = 132
const FUGUE = 40 // the fugue begins (before it: the canon)
const TUTTI = 112 // the stretto or the last entry, and the coda: everyone
const C4 = 440 * 2 ** (-9 / 12) // 261.63 Hz, exact equal temperament
const PHASES = { canon: [0, FUGUE], fugue: [FUGUE, TUTTI], tutti: [TUTTI, END] }
// the note of a voice at x in the given phases (moved by dn semitones: a 4′ or a 16′ doubling) → { n, d, τ, u, at } or null
const playing = (list, x, phases, dn = 0) => {
  if (!phases.some(p => x >= PHASES[p][0] && x < PHASES[p][1])) return null
  const m = notesAt(list, x)
  return m && (dn ? { ...m, n: m.n + dn } : m)
}

